//! Excluded actual-gallery maintenance schedule preview and bounded native DOM replay.
use dioxus::prelude::*;
use dioxus_ix::*;

#[path = "../../examples/gallery/maintenance_schedule.rs"]
mod gallery_schedule;

#[component]
pub fn MaintenanceSchedulePreview() -> Element {
    let mut narrow = use_signal(|| false);
    #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
    let window = dioxus::desktop::window();
    rsx! {
        style { {STYLES} }
        style { {gallery_schedule::STYLES} }
        IxTheme { class: "maintenance-schedule-review",
            h1 { "Maintenance schedule" }
            Button { id: "maintenance-schedule-narrow", variant: ButtonVariant::Secondary,
                onclick: move |_| narrow.toggle(), if narrow() { "Use wide preview" } else { "Use narrow preview" }
            }
            div { id: "maintenance-schedule-frame", style: if narrow() { "width:340px;max-width:100%;min-width:0" } else { "width:960px;max-width:100%;min-width:0" },
                gallery_schedule::MaintenanceScheduleExample {}
            }
            div { onmounted: move |_| {
                #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
                {
                    let window = window.clone();
                    spawn(async move {
                        let query = crate::dom_query::eval(NATIVE_MAINTENANCE_SCHEDULE_CHECK);
                        if let Err(error) = query.send("maintenanceschedule") {
                            eprintln!("Maintenance schedule native driver failed to start: {error:?}");
                            std::process::exit(1);
                        }
                        match query.join::<serde_json::Value>().await {
                            Ok(result) if result["ok"] == true => {
                                println!("Dioxus native maintenance schedule: {result}");
                                window.close();
                            }
                            result => {
                                eprintln!("Dioxus native maintenance schedule failed: {result:?}");
                                std::process::exit(1);
                            }
                        }
                    });
                    spawn(async move {
                        futures_timer::Delay::new(std::time::Duration::from_secs(30)).await;
                        eprintln!("Maintenance schedule native driver timed out");
                        std::process::exit(1);
                    });
                }
            } }
        }
    }
}

const STYLES: &str = "body{margin:0}.maintenance-schedule-review{box-sizing:border-box;min-height:100vh;padding:24px}.maintenance-schedule-review>h1{font-size:28px;margin:0 0 24px}.maintenance-schedule-review h2{font-size:22px;margin:24px 0 16px}.maintenance-schedule-review p{max-width:72ch;line-height:1.5}#maintenance-schedule-frame{margin-top:24px}@media(max-width:600px){.maintenance-schedule-review{padding:16px}}";

